from __future__ import annotations

from app.models import LiteratureReference, LocalizedText, TemplateDefinition, TemplateField


def L(zh: str, en: str) -> LocalizedText:
    return LocalizedText(zh=zh, en=en)


TIMEFRAME_OPTIONS = ["1m", "3m", "5m", "15m", "30m", "1h", "4h", "1d"]
INDICATOR_OPTIONS = ["SMA", "EMA", "WMA", "TEMA", "DEMA"]
PRICE_SOURCE_OPTIONS = ["close", "open", "high", "low", "hl2", "ohlc4"]
CROSS_DIRECTION_OPTIONS = ["cross_above", "cross_below"]
TREND_FILTER_OPTIONS = ["off", "EMA", "SMA"]
THRESHOLD_INDICATOR_OPTIONS = ["RSI", "CCI", "MFI", "WILLR"]
THRESHOLD_DIRECTION_OPTIONS = ["below_entry_above_exit", "above_entry_below_exit"]
REGIME_FILTER_OPTIONS = ["ema200_uptrend", "adx_strength", "low_volatility"]
BASE_LOGIC_OPTIONS = ["rsi_reversion", "ema_trend", "channel_breakout"]


def common_fields(default_name: str, default_roi: float, default_stoploss: float):
    return [
        TemplateField(
            name="strategy_name",
            label=L("策略名称", "Strategy Name"),
            type="str",
            default=default_name,
            help=L("将同时作为 Python class 名和输出文件名。", "Used as both the Python class name and the output filename."),
            group="identity",
        ),
        TemplateField(
            name="timeframe",
            label=L("周期", "Timeframe"),
            type="select",
            default="5m",
            options=TIMEFRAME_OPTIONS,
            help=L("应与回测数据周期保持一致。", "Should usually match the backtest data timeframe."),
            group="general",
        ),
        TemplateField(
            name="minimal_roi",
            label=L("最小 ROI", "Minimal ROI"),
            type="float",
            default=default_roi,
            help=L("达到该收益后允许退出。", "Profit threshold before exits are allowed."),
            group="risk",
        ),
        TemplateField(
            name="stoploss",
            label=L("止损", "Stoploss"),
            type="float",
            default=default_stoploss,
            help=L("必须是负数。", "Must be a negative number."),
            group="risk",
        ),
        TemplateField(
            name="export_plot_config",
            label=L("导出绘图配置", "Export Plot Config"),
            type="bool",
            default=True,
            help=L("自动导出基础 plot_config，便于在图表中叠加指标。", "Export a simple plot_config so indicators can be overlaid in charts."),
            group="general",
        ),
    ]


