def _append_field_if_missing(template_key: str, field: TemplateField) -> None:
    tpl = TEMPLATES[template_key]
    if not any(existing.name == field.name for existing in tpl.fields):
        tpl.fields.append(field)


def _field_by_name(template_key: str, field_name: str):
    for field in TEMPLATES[template_key].fields:
        if field.name == field_name:
            return field
    return None


