def _generic_workbench_enrichment() -> None:
    """Fill workbench fields for templates that do not define them explicitly."""
    for tpl in TEMPLATES.values():
        if not tpl.suitable_market.zh:
            if tpl.market_regime == "trending":
                tpl.suitable_market = L("更适合趋势延续或趋势确认场景。", "Better suited to trend continuation or trend-confirmation settings.")
            elif tpl.market_regime in {"ranging", "intraday_range"}:
                tpl.suitable_market = L("更适合价格围绕均值波动的震荡场景。", "Better suited to range-bound markets where price oscillates around a mean.")
            elif tpl.market_regime == "breakout":
                tpl.suitable_market = L("更适合价格从区间或通道中突破的场景。", "Better suited to breakouts from ranges or channels.")
            else:
                tpl.suitable_market = L("适合需要根据市场状态调整逻辑的场景。", "Suitable when logic should adapt to market state.")
        if not tpl.signal_structure.zh:
            tpl.signal_structure = L("模板信号 → 可选过滤/确认 → 模板退出条件。", "Template signal → optional filters/confirmation → template exit condition.")
        if not tpl.sensitivity_notes.zh:
            tpl.sensitivity_notes = L("窗口越短通常越敏感但噪声更多；窗口越长更平滑但更滞后。", "Shorter windows are usually more sensitive but noisier; longer windows are smoother but more lagging.")
        if not tpl.risk_control_notes.zh:
            tpl.risk_control_notes = L("minimal_roi 和 stoploss 是基础风险参数；模板内的退出条件只是策略逻辑的一部分。", "minimal_roi and stoploss are base risk parameters; template exits are part of strategy logic.")
        if not tpl.overfit_notes.zh:
            tpl.overfit_notes = L("避免同时调太多参数；先确认策略假设，再逐步调整敏感度。", "Avoid tuning too many parameters at once; confirm the hypothesis before adjusting sensitivity.")
        if not tpl.confirmation_layers:
            tags = set(tpl.tags or [])
            layers = []
            if "volume" in tags or any("volume" in f.name for f in tpl.fields):
                layers.append("Volume")
            if "regime" in tags or tpl.market_regime == "adaptive":
                layers.append("Regime")
            if "filters" in tags:
                layers.append("Filter")
            if not layers:
                layers.append("Template-native signal")
            tpl.confirmation_layers = layers
        if not tpl.exit_modules:
            tpl.exit_modules = ["Template exit", "ROI/stoploss base parameters"]
        if not tpl.entry_logic.zh:
            tpl.entry_logic = L("根据该模板的核心指标生成入场条件；请在生成代码中确认具体逻辑。", "Entry conditions are generated from the template's core indicators; inspect generated code for exact logic.")
        if not tpl.exit_logic.zh:
            tpl.exit_logic = L("根据该模板的退出指标或反向条件生成退出信号。", "Exit signals are generated from the template's exit indicator or opposite condition.")
        if not tpl.risk_logic.zh:
            tpl.risk_logic = L("使用 minimal_roi、stoploss 与模板退出规则共同形成基础风险边界。", "Uses minimal_roi, stoploss, and template exits as the basic risk boundary.")
        if not tpl.weakness.zh:
            tpl.weakness = L("该模板是策略开发脚手架，不应在没有外部验证的情况下直接使用。", "This template is a strategy-development scaffold and should not be used without external validation.")
        if not tpl.development_notes.zh:
            tpl.development_notes = L("建议先写清楚策略假设，再调整参数并生成不同版本。", "Write down the strategy hypothesis first, then adjust parameters and generate separate versions.")


_generic_workbench_enrichment()

