# ===== v1.2.02 Literature References and Explanations =====
def _ref(title: str, authors: str, year: str, venue: str, url: str, zh_note: str, en_note: str) -> LiteratureReference:
    return LiteratureReference(
        title=title,
        authors=authors,
        year=year,
        venue=venue,
        url=url,
        note=L(zh_note, en_note),
    )


def _attach_literature_details(key: str, refs, explanation_zh: str, explanation_en: str, implementation_zh: str, implementation_en: str) -> None:
    tpl = TEMPLATES.get(key)
    if not tpl:
        return
    tpl.literature_references = refs
    tpl.literature_explanation = L(explanation_zh, explanation_en)
    tpl.literature_implementation_note = L(implementation_zh, implementation_en)
    if "cited_literature" not in tpl.tags:
        tpl.tags.append("cited_literature")
    if "v1202" not in tpl.tags:
        tpl.tags.append("v1202")


